// In-app PWA update service (v3.1.1 -- Settings "Pembaruan Aplikasi /
// Application Update").
//
// WHAT COUNTS AS "AN UPDATE IS AVAILABLE"
// The deployed service-worker.js script itself is the release metadata.
// service-worker.js embeds APP_VERSION (test-enforced identical to
// js/shared/app-version.js) and ASSET_REVISION (a deterministic content
// hash of every precached APP_SHELL file, regenerated by
// tests/tools/sync-service-worker-release.mjs and test-enforced), so ANY
// release that changes a cached asset changes the worker's bytes, and the
// browser's own byte-comparison update check -- registration.update() --
// detects it. There is deliberately no separate version.json: it would be
// a second public version value that could disagree with what is actually
// deployed. A version is only reported as "ready" once the new worker has
// finished precaching the complete APP_SHELL AND verified that the
// precached js/shared/app-version.js matches its own APP_VERSION (see
// service-worker.js's install handler) -- so a half-propagated deployment
// (fresh service-worker.js, stale CDN asset) fails installation instead
// of being offered as an update.
//
// The "latest version" shown to the user is read FROM the installed
// waiting worker (GET_VERSION message), i.e. only when it is reliably
// known; it is never derived from a cached file, a GitHub commit, or a
// guess.
//
// RELOAD POLICY (Owner requirement): this module NEVER reloads the page
// on its own. The only path to location.reload() is applyUpdate(), which
// the Settings page calls exclusively from the user's own "Perbarui
// Sekarang / Update Now" click. Even then it reloads exactly once, and
// only after the new worker has actually taken control
// ('controllerchange'). It never touches localStorage, IndexedDB, Cache
// Storage, or the service-worker registration itself (no clear(), no
// unregister()) -- persistent application data is outside its reach by
// construction. The one thing it writes is a short-lived sessionStorage
// note ("an update to vX was requested") so the reloaded page can confirm
// the new version is genuinely active before saying so.
//
// Written against an injectable environment (navigator, timers,
// sessionStorage, reload, MessageChannel) so the full lifecycle can be
// exercised under Node's test runner without a browser
// (tests/app-update-service.test.mjs).
import { APP_VERSION } from '../shared/app-version.js';

export const UPDATE_STATUS = Object.freeze({
  IDLE: 'idle',
  CHECKING: 'checking',
  CURRENT: 'current',
  AVAILABLE: 'available',
  DOWNLOADING: 'downloading',
  READY: 'ready',
  APPLYING: 'applying',
  OFFLINE: 'offline',
  ERROR: 'error',
  UNSUPPORTED: 'unsupported',
});

export const UPDATE_ERROR = Object.freeze({
  NETWORK: 'network',
  INSTALL_FAILED: 'install-failed',
  APPLY_FAILED: 'apply-failed',
  NO_REGISTRATION: 'no-registration',
});

// Mirrored verbatim in service-worker.js (a classic worker script cannot
// import this ES module) -- tests/service-worker.test.mjs asserts the two
// stay identical.
export const SW_MESSAGE = Object.freeze({
  SKIP_WAITING: 'HPAL_SW_SKIP_WAITING',
  GET_VERSION: 'HPAL_SW_GET_VERSION',
  VERSION: 'HPAL_SW_VERSION',
});

export const PENDING_UPDATE_STORAGE_KEY = 'hpal.appUpdate.pendingReload';

const DEFAULT_TIMEOUTS = Object.freeze({
  registration: 10000,
  version: 3000,
  apply: 15000,
});
const DEFAULT_AUTO_CHECK_INTERVAL_MS = 5 * 60 * 1000;
const PENDING_MAX_AGE_MS = 10 * 60 * 1000;

const BUSY_STATUSES = new Set([
  UPDATE_STATUS.CHECKING,
  UPDATE_STATUS.AVAILABLE,
  UPDATE_STATUS.DOWNLOADING,
  UPDATE_STATUS.APPLYING,
]);

/* ============================================================
   SEMANTIC VERSIONS
============================================================ */
const SEMVER_PATTERN = /^[vV]?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z.-]+)?$/;

// Returns { major, minor, patch, prerelease: string[] } or null.
export function parseVersion(value) {
  if (typeof value !== 'string') return null;
  const match = value.trim().match(SEMVER_PATTERN);
  if (!match) return null;
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3]),
    prerelease: match[4] ? match[4].split('.') : [],
  };
}

function compareIdentifiers(a, b) {
  const aNumeric = /^\d+$/.test(a);
  const bNumeric = /^\d+$/.test(b);
  if (aNumeric && bNumeric) return Math.sign(Number(a) - Number(b));
  if (aNumeric) return -1;
  if (bNumeric) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

// SemVer 2.0.0 precedence: -1 / 0 / 1, or NaN when either side is not a
// valid version (never silently treated as "equal"). Build metadata is
// ignored; a leading "v" is accepted (APP_VERSION's own format).
export function compareVersions(a, b) {
  const left = parseVersion(a);
  const right = parseVersion(b);
  if (!left || !right) return NaN;
  for (const part of ['major', 'minor', 'patch']) {
    if (left[part] !== right[part]) return left[part] > right[part] ? 1 : -1;
  }
  const lp = left.prerelease;
  const rp = right.prerelease;
  if (!lp.length && !rp.length) return 0;
  if (!lp.length) return 1;
  if (!rp.length) return -1;
  for (let i = 0; i < Math.max(lp.length, rp.length); i++) {
    if (i >= lp.length) return -1;
    if (i >= rp.length) return 1;
    const cmp = compareIdentifiers(lp[i], rp[i]);
    if (cmp !== 0) return cmp;
  }
  return 0;
}

/* ============================================================
   CONTROLLER
============================================================ */
function defaultSessionStorage() {
  try {
    return globalThis.sessionStorage || null;
  } catch {
    return null;
  }
}

export function createAppUpdateController(options = {}) {
  const nav = 'navigator' in options ? options.navigator : globalThis.navigator;
  const installedVersion = options.installedVersion || APP_VERSION;
  const reload = options.reload || (() => globalThis.location.reload());
  const storage = 'sessionStorage' in options ? options.sessionStorage : defaultSessionStorage();
  const setTimer = options.setTimeout || ((fn, ms) => globalThis.setTimeout(fn, ms));
  const clearTimer = options.clearTimeout || ((id) => globalThis.clearTimeout(id));
  const now = options.now || (() => Date.now());
  const MessageChannelImpl = 'MessageChannel' in options ? options.MessageChannel : globalThis.MessageChannel;
  const timeouts = { ...DEFAULT_TIMEOUTS, ...(options.timeouts || {}) };
  const autoCheckIntervalMs = options.autoCheckIntervalMs ?? DEFAULT_AUTO_CHECK_INTERVAL_MS;

  let state = Object.freeze({
    status: UPDATE_STATUS.IDLE,
    installedVersion,
    latestVersion: null,
    error: null,
    lastCheckedAt: null,
  });
  const listeners = new Set();

  let checkPromise = null;
  let lastAutoCheckAt = null;
  let watchedRegistration = null;
  let trackedInstalling = null;
  let readyWorker = null;
  let applyRequested = false;
  let reloadTriggered = false;
  let applyTimer = null;
  let applyCleanup = null;

  function setState(patch) {
    state = Object.freeze({ ...state, ...patch });
    listeners.forEach((fn) => {
      try {
        fn(state);
      } catch {
        // A rendering subscriber's failure must never break the update lifecycle.
      }
    });
  }

  function isSupported() {
    return !!(nav && nav.serviceWorker && typeof nav.serviceWorker.getRegistration === 'function');
  }

  function isOnline() {
    return !nav || nav.onLine !== false;
  }

  function withTimeout(promise, ms, fallback) {
    return new Promise((resolve) => {
      const timer = setTimer(() => resolve(fallback), ms);
      Promise.resolve(promise).then(
        (value) => { clearTimer(timer); resolve(value); },
        () => { clearTimer(timer); resolve(fallback); },
      );
    });
  }

  async function resolveRegistration() {
    const registration = await nav.serviceWorker.getRegistration();
    if (registration) return registration;
    // index.html registers the worker on window 'load' -- a check issued
    // before that (Settings opened as the very first route) briefly waits
    // for it rather than reporting a false failure.
    if (!nav.serviceWorker.ready) return null;
    return withTimeout(nav.serviceWorker.ready, timeouts.registration, null);
  }

  function watchRegistration(registration) {
    if (watchedRegistration === registration) return;
    watchedRegistration = registration;
    if (typeof registration.addEventListener === 'function') {
      registration.addEventListener('updatefound', () => {
        if (watchedRegistration === registration) trackInstalling(registration, registration.installing);
      });
    }
  }

  function trackInstalling(registration, worker) {
    if (!worker || worker === trackedInstalling || applyRequested) return;
    trackedInstalling = worker;
    readyWorker = null;
    setState({ status: UPDATE_STATUS.AVAILABLE, latestVersion: null, error: null });
    setState({ status: UPDATE_STATUS.DOWNLOADING });
    if (typeof worker.addEventListener === 'function') {
      worker.addEventListener('statechange', () => onInstallingStateChange(registration, worker));
    }
    onInstallingStateChange(registration, worker);
  }

  function onInstallingStateChange(registration, worker) {
    if (worker !== trackedInstalling || applyRequested) return;
    const workerState = worker.state;

    if (workerState === 'installed') {
      trackedInstalling = null;
      if (registration.waiting) {
        enterReady(registration.waiting);
      } else {
        // No previously active worker (first install), so it activates
        // straight away; nothing is waiting to be applied.
        setState({ status: UPDATE_STATUS.CURRENT, latestVersion: installedVersion, error: null });
      }
      return;
    }

    if (workerState === 'activating' || workerState === 'activated') {
      trackedInstalling = null;
      setState({ status: UPDATE_STATUS.CURRENT, latestVersion: installedVersion, error: null });
      return;
    }

    if (workerState === 'redundant') {
      trackedInstalling = null;
      if (registration.installing && registration.installing !== worker) {
        trackInstalling(registration, registration.installing);
      } else if (registration.waiting) {
        enterReady(registration.waiting);
      } else {
        // Precache download failed, or the deployed assets did not match
        // the new worker's APP_VERSION (deployment still propagating).
        setState({ status: UPDATE_STATUS.ERROR, latestVersion: null, error: UPDATE_ERROR.INSTALL_FAILED });
      }
    }
  }

  function enterReady(waitingWorker) {
    if (applyRequested) return;
    const alreadyReadyForThisWorker = readyWorker === waitingWorker && state.status === UPDATE_STATUS.READY;
    readyWorker = waitingWorker;
    if (!alreadyReadyForThisWorker) {
      setState({ status: UPDATE_STATUS.READY, latestVersion: null, error: null });
    }
    if (state.latestVersion) return;
    requestWorkerVersion(waitingWorker).then((version) => {
      if (version && readyWorker === waitingWorker && state.status === UPDATE_STATUS.READY) {
        setState({ latestVersion: version });
      }
    });
  }

  function requestWorkerVersion(worker) {
    if (!worker || typeof worker.postMessage !== 'function' || typeof MessageChannelImpl !== 'function') {
      return Promise.resolve(null);
    }
    return new Promise((resolve) => {
      const channel = new MessageChannelImpl();
      let settled = false;
      let timer = null;
      const finish = (value) => {
        if (settled) return;
        settled = true;
        if (timer !== null) clearTimer(timer);
        try { channel.port1.close(); } catch { /* already closed */ }
        resolve(value);
      };
      timer = setTimer(() => finish(null), timeouts.version);
      channel.port1.onmessage = (event) => {
        const data = event && event.data;
        const ok = data && data.type === SW_MESSAGE.VERSION && parseVersion(data.version);
        finish(ok ? data.version : null);
      };
      try {
        worker.postMessage({ type: SW_MESSAGE.GET_VERSION }, [channel.port2]);
      } catch {
        finish(null);
      }
    });
  }

  async function runCheck() {
    if (!isSupported()) {
      setState({ status: UPDATE_STATUS.UNSUPPORTED, error: null });
      return state;
    }

    let registration = null;
    try {
      registration = await resolveRegistration();
    } catch {
      registration = null;
    }
    if (!registration) {
      setState(isOnline()
        ? { status: UPDATE_STATUS.ERROR, error: UPDATE_ERROR.NO_REGISTRATION }
        : { status: UPDATE_STATUS.OFFLINE, error: null });
      return state;
    }
    watchRegistration(registration);

    // An update that is already fully downloaded can be installed even
    // while offline -- its assets are already in Cache Storage.
    if (registration.installing) {
      trackInstalling(registration, registration.installing);
      return state;
    }
    if (registration.waiting) {
      enterReady(registration.waiting);
      return state;
    }

    if (!isOnline()) {
      // Never "already up to date" -- nothing could be checked.
      setState({ status: UPDATE_STATUS.OFFLINE, error: null });
      return state;
    }

    setState({ status: UPDATE_STATUS.CHECKING, error: null });
    try {
      // Fetches the deployed service-worker.js bypassing the HTTP cache
      // (index.html registers with updateViaCache: 'none'; the main
      // script is never served by the worker's own fetch handler).
      await registration.update();
    } catch {
      setState(isOnline()
        ? { status: UPDATE_STATUS.ERROR, error: UPDATE_ERROR.NETWORK, lastCheckedAt: now() }
        : { status: UPDATE_STATUS.OFFLINE, error: null, lastCheckedAt: now() });
      return state;
    }

    setState({ lastCheckedAt: now() });
    if (registration.installing) {
      trackInstalling(registration, registration.installing);
    } else if (registration.waiting) {
      enterReady(registration.waiting);
    } else if (state.status === UPDATE_STATUS.CHECKING) {
      setState({ status: UPDATE_STATUS.CURRENT, latestVersion: installedVersion, error: null });
    }
    return state;
  }

  function checkForUpdates() {
    if (state.status === UPDATE_STATUS.APPLYING) return Promise.resolve(state);
    if (checkPromise) return checkPromise;
    checkPromise = runCheck().finally(() => {
      checkPromise = null;
    });
    return checkPromise;
  }

  // Settings-open trigger: throttled, and never interrupts an update that
  // is already downloading/ready/applying. Offline/error results are
  // re-checked on the next opportunity rather than throttled.
  function autoCheck() {
    if (BUSY_STATUSES.has(state.status) || state.status === UPDATE_STATUS.READY) return Promise.resolve(state);
    const t = now();
    const recentlyChecked = lastAutoCheckAt !== null && t - lastAutoCheckAt < autoCheckIntervalMs;
    const retryable = state.status === UPDATE_STATUS.OFFLINE || state.status === UPDATE_STATUS.ERROR;
    if (recentlyChecked && !retryable) return Promise.resolve(state);
    lastAutoCheckAt = t;
    return checkForUpdates();
  }

  function writePendingReload(record) {
    if (!storage) return;
    try {
      storage.setItem(PENDING_UPDATE_STORAGE_KEY, JSON.stringify(record));
    } catch {
      // Private mode / quota -- only the post-reload confirmation is lost.
    }
  }

  function clearPendingReload() {
    if (!storage) return;
    try {
      storage.removeItem(PENDING_UPDATE_STORAGE_KEY);
    } catch {
      // ignore
    }
  }

  function readPendingReload() {
    if (!storage) return null;
    try {
      const raw = storage.getItem(PENDING_UPDATE_STORAGE_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }

  function triggerReload() {
    if (!applyRequested || reloadTriggered) return;
    reloadTriggered = true;
    if (applyTimer !== null) clearTimer(applyTimer);
    applyTimer = null;
    if (applyCleanup) applyCleanup();
    reload();
  }

  function failApply() {
    if (reloadTriggered) return;
    if (applyTimer !== null) clearTimer(applyTimer);
    applyTimer = null;
    if (applyCleanup) applyCleanup();
    applyRequested = false;
    clearPendingReload();
    setState({ status: UPDATE_STATUS.ERROR, error: UPDATE_ERROR.APPLY_FAILED });
  }

  // Called ONLY from the user's own "Update Now" click. Returns true when
  // activation was requested.
  function applyUpdate() {
    if (applyRequested || state.status !== UPDATE_STATUS.READY) return false;
    const waiting = watchedRegistration && watchedRegistration.waiting;
    if (!waiting || typeof waiting.postMessage !== 'function') {
      setState({ status: UPDATE_STATUS.ERROR, error: UPDATE_ERROR.APPLY_FAILED });
      return false;
    }

    applyRequested = true;
    setState({ status: UPDATE_STATUS.APPLYING, error: null });
    writePendingReload({ from: installedVersion, target: state.latestVersion, requestedAt: now() });

    const container = nav.serviceWorker;
    const onControllerChange = () => triggerReload();
    const onWaitingStateChange = () => {
      if (waiting.state === 'redundant') failApply();
    };
    container.addEventListener('controllerchange', onControllerChange);
    if (typeof waiting.addEventListener === 'function') waiting.addEventListener('statechange', onWaitingStateChange);
    applyCleanup = () => {
      container.removeEventListener('controllerchange', onControllerChange);
      if (typeof waiting.removeEventListener === 'function') waiting.removeEventListener('statechange', onWaitingStateChange);
      applyCleanup = null;
    };

    applyTimer = setTimer(() => {
      applyTimer = null;
      // The new worker became active but this page never saw
      // 'controllerchange' (e.g. it was not controlled) -- the user already
      // asked for the reload, and the new version IS active.
      if (waiting.state === 'activating' || waiting.state === 'activated') triggerReload();
      else failApply();
    }, timeouts.apply);

    try {
      waiting.postMessage({ type: SW_MESSAGE.SKIP_WAITING });
    } catch {
      failApply();
      return false;
    }
    return true;
  }

  // Called once at startup: if this page load is the reload applyUpdate()
  // performed, report whether the requested version is now the one
  // actually running. Returns null when there is nothing to report.
  //   { ok: true,  version }           -- verified: running == requested
  //   { ok: false, version, target }   -- still not on the requested version
  //   { ok: null,  version }           -- reloaded, target version unknown
  function consumePostUpdateResult() {
    const pending = readPendingReload();
    if (!pending) return null;
    clearPendingReload();
    if (typeof pending.requestedAt !== 'number' || now() - pending.requestedAt > PENDING_MAX_AGE_MS) return null;
    if (parseVersion(pending.target)) {
      const ok = compareVersions(installedVersion, pending.target) === 0;
      return ok ? { ok: true, version: installedVersion } : { ok: false, version: installedVersion, target: pending.target };
    }
    return { ok: null, version: installedVersion };
  }

  function subscribe(fn) {
    listeners.add(fn);
    return () => listeners.delete(fn);
  }

  return {
    getState: () => state,
    subscribe,
    checkForUpdates,
    autoCheck,
    applyUpdate,
    consumePostUpdateResult,
  };
}

let defaultController = null;

// The app-wide instance Settings uses (survives Settings' access-tier DOM
// rebuilds -- the state lives here, not in the DOM).
export function getAppUpdateController() {
  if (!defaultController) defaultController = createAppUpdateController();
  return defaultController;
}
